const _k=["MWU=","N2M0","M3lf","bl9r","czFn","djJf"];function deriveKey(){return atob(_k.slice().reverse().join(""))}const enc=new TextEncoder;async function sha256hex(n){const t=await crypto.subtle.digest("SHA-256",enc.encode(n));return[...new Uint8Array(t)].map(e=>e.toString(16).padStart(2,"0")).join("")}async function sign(n){const t=await crypto.subtle.importKey("raw",enc.encode(deriveKey()),{name:"HMAC",hash:"SHA-256"},!1,["sign"]),e=await crypto.subtle.sign("HMAC",t,enc.encode(n));return btoa(String.fromCharCode(...new Uint8Array(e)))}async function send(n){const t="/api/tp08/v2/transfer",e=Math.floor(Date.now()/1e3).toString(),o=JSON.stringify(n),s=[e,"POST",t,await sha256hex(o)].join("|"),a=await fetch(t,{method:"POST",headers:{"Content-Type":"application/json","X-Req-Ts":e,"X-Req-Sig":await sign(s)},body:o});return{status:a.status,json:await a.json()}}document.getElementById("send").addEventListener("click",async()=>{const n=document.getElementById("out");n.textContent="Envoi\u2026";try{const t=await send({to:document.getElementById("to").value,amount:Number(document.getElementById("amount").value)});n.textContent=t.status+`
`+JSON.stringify(t.json,null,2)}catch(t){n.textContent="Erreur : "+t}});
